-- Lifeline Multi-Speciality Hospital demo data. Run AFTER the 3 business-page migrations.
-- Upload the images folder to <uploads>/uploads/demo/hospital/ separately.
SET NAMES utf8mb4;
START TRANSACTION;

-- Existing records this data hangs off (same fallbacks as the seeder).
SET @city = COALESCE((SELECT id FROM cities WHERE slug = 'jhansi' LIMIT 1), (SELECT id FROM cities ORDER BY id LIMIT 1));
SET @plan = COALESCE((SELECT id FROM vip_plans WHERE slug = 'premium' LIMIT 1), (SELECT id FROM vip_plans ORDER BY product_limit DESC LIMIT 1));
-- Only a user that really exists (role rows can outlive a deleted user); NULL if none.
SET @partner = COALESCE((SELECT id FROM users WHERE email = 'jhansi.managerA@globallife.in' LIMIT 1), (SELECT u.id FROM model_has_roles mr JOIN roles r ON r.id = mr.role_id JOIN users u ON u.id = mr.model_id WHERE r.name = 'commission_partner' AND mr.model_type = 'App\\Models\\User' ORDER BY u.id LIMIT 1));
INSERT IGNORE INTO `roles` (`name`, `guard_name`, `created_at`, `updated_at`) VALUES ('vip_member', 'web', NOW(), NOW()), ('customer', 'web', NOW(), NOW());

-- Hospital owner login: hospital@globallife.in / Password!123
INSERT INTO `users` (`name`, `email`, `mobile`, `email_verified_at`, `password`, `status`, `commission_percentage`, `created_by`, `two_factor_secret`, `two_factor_recovery_codes`, `two_factor_confirmed_at`, `remember_token`, `created_at`, `updated_at`)
VALUES ('Dr. Rajesh Agarwal', 'hospital@globallife.in', '9876500001', '2026-10-30 09:15:03', '$2y$12$kfQHKor0vJMyQSr.oGfhwOustAyXYfzslkgN61qWJmrUu7YX6bFQ2', 'active', NULL, @partner, NULL, NULL, NULL, NULL, '2026-10-30 09:15:03', '2026-10-30 13:26:56');
SET @owner = LAST_INSERT_ID();
INSERT INTO `model_has_roles` (`role_id`, `model_type`, `model_id`) SELECT id, 'App\\Models\\User', @owner FROM roles WHERE name = 'vip_member' AND guard_name = 'web';

