VALUES (@owner, @city, @plan, 'Lifeline Multi-Speciality Hospital', 'Healthcare', 'Multi-Speciality Hospital', 'Dr. Rajesh Agarwal', 'lifeline-multispeciality-hospital', 'Since 2006, Lifeline has cared for more than one lakh families across Jhansi and Bundelkhand.\n\nOur 60+ specialists work across 25 departments, backed by a modular operation theatre complex, a cath lab, a 128-slice CT scanner, a level-III NICU and an in-house blood bank. Every patient gets one care coordinator from admission to discharge, transparent package pricing, and cashless treatment with all major insurers and government schemes.', 'Bundelkhand’s trusted 250-bed multi-speciality hospital — expert doctors, modern technology and 24×7 emergency care under one roof.', 2006, '09AABCL1234F1Z5', NULL, NULL, 'uploads/demo/hospital/logo.svg', 'uploads/demo/hospital/about.svg', 'care@lifelinehospital.in', '9876500001', '05102470001', '9876500001', NULL, 'NH-44, Gwalior Road, near Medical College Crossing, Jhansi, Uttar Pradesh 284001', 'https://maps.google.com/?q=Medical+College+Jhansi', '{\"monday\":{\"open\":\"00:00\",\"close\":\"23:59\",\"closed\":false},\"tuesday\":{\"open\":\"00:00\",\"close\":\"23:59\",\"closed\":false},\"wednesday\":{\"open\":\"00:00\",\"close\":\"23:59\",\"closed\":false},\"thursday\":{\"open\":\"00:00\",\"close\":\"23:59\",\"closed\":false},\"friday\":{\"open\":\"00:00\",\"close\":\"23:59\",\"closed\":false},\"saturday\":{\"open\":\"00:00\",\"close\":\"23:59\",\"closed\":false},\"sunday\":{\"open\":\"00:00\",\"close\":\"23:59\",\"closed\":false}}', NULL, 'https://facebook.com/', 'https://instagram.com/', 'https://youtube.com/', NULL, NULL, NULL, NULL, '{\"videos\":false,\"banner\":true,\"about\":true,\"stats\":true,\"shop\":true,\"services\":true,\"products\":true,\"gallery\":true,\"reviews\":true,\"contact\":true,\"faqs\":true,\"social_media\":true,\"float_whatsapp\":true,\"float_call\":true,\"float_direction\":true,\"float_email\":true}', NULL, 'KBSIYGB', 'active', '2026-08-30 13:26:56', '2027-08-30 13:26:56', '2026-10-30 09:15:03', '2026-10-30 13:26:57');
SET @ms = LAST_INSERT_ID();

