VALUES (@ms, 'uploads/demo/hospital/service-cardiology.svg', 'Cardiology', 'cardiology', 'Angiography, angioplasty, pacemakers and bypass surgery by a 5-member heart team.', '• 24×7 cath lab with primary angioplasty for heart attacks\n• Echo, TMT, Holter and ECG under one roof\n• Cardiac ICU with 12 beds\n• Heart failure and hypertension clinic every Thursday', 'Heart', NULL, '800.00', '600.00', '25.00', NULL, 1, 'Cardiology', 'Angiography, angioplasty, pacemakers and bypass surgery by a 5-member heart team.', NULL, 'published', 1, 0, 1, '2026-10-30 13:26:56', '2026-10-30 13:26:56');
