VALUES (@ms, 'uploads/demo/hospital/service-neurology-neurosurgery.svg', 'Neurology & Neurosurgery', 'neurology-neurosurgery', 'Stroke unit, epilepsy care and minimally invasive spine surgery.', '• Thrombolysis-ready stroke unit (golden hour protocol)\n• EEG, EMG and nerve conduction studies\n• Microscopic brain and spine surgery', 'Brain & Spine', NULL, '900.00', NULL, NULL, NULL, 1, 'Neurology & Neurosurgery', 'Stroke unit, epilepsy care and minimally invasive spine surgery.', NULL, 'published', 1, 1, 1, '2026-10-30 13:26:56', '2026-10-30 13:26:56');
