-- business_faqs (6)
INSERT INTO `business_faqs` (`vip_microsite_id`, `question`, `answer`, `sort_order`, `is_visible`, `created_at`, `updated_at`)
VALUES (@ms, 'Is the emergency open at night?', 'Yes. Our emergency, ICU, pharmacy, lab and ambulance run 24 hours a day, 365 days a year. Call 98765 00001.', 0, 1, '2026-10-30 13:26:57', '2026-10-30 13:26:57');
INSERT INTO `business_faqs` (`vip_microsite_id`, `question`, `answer`, `sort_order`, `is_visible`, `created_at`, `updated_at`)
VALUES (@ms, 'Do you accept Ayushman Bharat and health insurance?', 'Yes. We are empanelled under Ayushman Bharat (PM-JAY), CGHS and ECHS, and offer cashless treatment with 40+ insurers and TPAs. Bring your card and a photo ID.', 1, 1, '2026-10-30 13:26:57', '2026-10-30 13:26:57');
INSERT INTO `business_faqs` (`vip_microsite_id`, `question`, `answer`, `sort_order`, `is_visible`, `created_at`, `updated_at`)
VALUES (@ms, 'How do I book a doctor’s appointment?', 'Call or WhatsApp 98765 00001, or use the enquiry form on this page. Walk-ins are welcome; booked patients are seen first.', 2, 1, '2026-10-30 13:26:57', '2026-10-30 13:26:57');
INSERT INTO `business_faqs` (`vip_microsite_id`, `question`, `answer`, `sort_order`, `is_visible`, `created_at`, `updated_at`)
VALUES (@ms, 'What should I bring for admission?', 'Photo ID, insurance card or policy copy, previous reports and the medicines you currently take.', 3, 1, '2026-10-30 13:26:57', '2026-10-30 13:26:57');
INSERT INTO `business_faqs` (`vip_microsite_id`, `question`, `answer`, `sort_order`, `is_visible`, `created_at`, `updated_at`)
VALUES (@ms, 'Are visiting hours fixed?', 'Wards: 11 am – 1 pm and 5 pm – 7 pm. ICU: one attendant at a time, 5 pm – 6 pm.', 4, 1, '2026-10-30 13:26:57', '2026-10-30 13:26:57');
INSERT INTO `business_faqs` (`vip_microsite_id`, `question`, `answer`, `sort_order`, `is_visible`, `created_at`, `updated_at`)
VALUES (@ms, 'Do you deliver medicines and devices at home?', 'Yes. Order from our Health Store on this page; our pharmacy team delivers across Jhansi, usually the same day.', 5, 1, '2026-10-30 13:26:57', '2026-10-30 13:26:57');

